package com.digitalhealth.model;
import jakarta.persistence.*; import java.time.*;
@Entity @Table(name="consents",indexes=@Index(name="idx_consent_worker_provider",columnList="worker_id,provider")) public class Consent { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="worker_id",nullable=false) private Worker worker; @Column(nullable=false) private String provider; @Column(nullable=false) private LocalDate grantedDate; private LocalDate expiryDate; @Column(nullable=false) private String status="ACTIVE"; @Column(nullable=false) private String purpose; public Long getId(){return id;} public Worker getWorker(){return worker;} public void setWorker(Worker x){worker=x;} public String getProvider(){return provider;} public void setProvider(String x){provider=x;} public LocalDate getGrantedDate(){return grantedDate;} public void setGrantedDate(LocalDate x){grantedDate=x;} public LocalDate getExpiryDate(){return expiryDate;} public void setExpiryDate(LocalDate x){expiryDate=x;} public String getStatus(){return status;} public void setStatus(String x){status=x;} public String getPurpose(){return purpose;} public void setPurpose(String x){purpose=x;} }
